        return best

    marker = max((v for v in counts if v != bg), key=longest_run)
    mark = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == marker]

    # Locate the distinctive right-angle marker's elbow.
    row_counts = Counter(r for r, c in mark)
    col_counts = Counter(c for r, c in mark)
    elbow_r = row_counts.most_common(1)[0][0]
    elbow_c = col_counts.most_common(1)[0][0]

    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color in (bg, marker) or (r, c) in seen:
